// CNSH CONFLICT DETECTION ENGINE
// DNA: CNSH::FUNC::CONFLICT_DETECT::v2.0
// 🔴 CONFLICT FLAG: Identifies contradictions between AI outputs

const block = $('Notion Trigger').item.json;
const gptOutput = JSON.parse($('OpenAI GPT Block Processor').item.json.choices?.[0]?.message?.content || '{}');
const claudeAudit = JSON.parse($('Claude Logic Auditor').item.json.content?.[0]?.text?.value || '{}');

// Conflict detection rules
let conflictFlag = false;
let conflictReasons = [];
let finalValueScore = gptOutput.value_score || 50;
let finalRiskScore = Math.max(
  gptOutput.risk_score || 0,
  Math.round((claudeAudit.risk_score || 0) * 100)
);

// Rule 1: High hallucination detected
if ((claudeAudit.hallucination || 0) > 0.5) {
  conflictFlag = true;
  conflictReasons.push('HALLUCINATION>0.5');
  finalValueScore = Math.floor(finalValueScore * 0.5);
}

// Rule 2: Low logic score
if ((claudeAudit.logic_score || 100) < 50) {
  conflictFlag = true;
  conflictReasons.push('LOGIC<50');
  finalRiskScore = Math.min(100, finalRiskScore + 30);
}

// Rule 3: High bias detected
if ((claudeAudit.bias || 0) > 0.7) {
  conflictFlag = true;
  conflictReasons.push('BIAS>0.7');
}

// Rule 4: AI consensus too low
if ((claudeAudit.consensus_score || 100) < 40) {
  conflictFlag = true;
  conflictReasons.push('CONSENSUS<40');
}

// Tricolor audit marker
let auditMarker = '🟢';
if (finalRiskScore >= 70 || conflictFlag) {
  auditMarker = '🔴';
} else if (finalRiskScore >= 40) {
  auditMarker = '🟡';
}

return [{
  json: {
    conflict_flag: conflictFlag,
    conflict_reasons: conflictReasons,
    final_value_score: Math.min(100, Math.max(0, finalValueScore)),
    final_risk_score: Math.min(100, Math.max(0, finalRiskScore)),
    hallucination_score: claudeAudit.hallucination || 0,
    bias_score: claudeAudit.bias || 0,
    logic_score: claudeAudit.logic_score || 50,
    consensus_score: claudeAudit.consensus_score || 50,
    audit_marker: auditMarker,
    gpt_raw: gptOutput,
    claude_raw: claudeAudit,
    block_id: block.id,
    dna_trace: 'CNSH::CONFLICT::' + new Date().toISOString(),
    _tricolor: {
      red: conflictFlag || finalRiskScore >= 70,
      yellow: !conflictFlag && finalRiskScore >= 40 && finalRiskScore < 70,
      green: !conflictFlag && finalRiskScore < 40 && finalValueScore >= 85
    }
  }
}];

// CNSH BLOCK SLICING ENGINE
// DNA: CNSH::FUNC::BLOCK_SLICE::v2.0
// Splits BLOCK_CONTENT into semantic chunks with overlap

const blockContent = $('Notion Trigger').item.json.properties?.CONTENT?.rich_text?.[0]?.text?.content || '';
const gptOutput = $('Function: Conflict Detection').item.json.gpt_raw || {};

// Use GPT chunks if available, otherwise slice by semantic boundaries
let chunks = gptOutput.chunks || [];

if (chunks.length === 0 && blockContent) {
  // Semantic slicing: split by paragraphs, then by sentences if needed
  const paragraphs = blockContent.split(/\n{2,}|(?<=[。！？.!?])\s+/).filter(p => p.trim().length > 0);

  for (const para of paragraphs) {
    if (para.length > 500) {
      // Further split long paragraphs by sentences
      const sentences = para.match(/[^。！？.!?]+[。！？.!?]+/g) || [para];
      let currentChunk = '';

      for (const sentence of sentences) {
        if ((currentChunk + sentence).length > 400) {
          if (currentChunk) chunks.push(currentChunk.trim());
          currentChunk = sentence;
        } else {
          currentChunk += sentence;
        }
      }
      if (currentChunk) chunks.push(currentChunk.trim());
    } else {
      chunks.push(para.trim());
    }
  }
}

// Generate chunk metadata
const chunkData = chunks.map((chunk, idx) => ({
  index: idx,
  content: chunk,
  length: chunk.length,
  embedding_target: true,
  semantic_role: idx === 0 ? 'lead' : idx === chunks.length - 1 ? 'conclusion' : 'body'
}));

return [{
  json: {
    original_length: blockContent.length,
    chunk_count: chunks.length,
    chunks: chunkData,
    overlap_ratio: 0.15,
    dna_trace: 'CNSH::SLICE::' + new Date().toISOString()
  }
}];

// CNSH DNA GENERATION ENGINE
// DNA: CNSH::FUNC::DNA_GEN::v2.0
// Generates SHA256-based DNA hash for block traceability

const crypto = require('crypto');
const block = $('Notion Trigger').item.json;
const conflictResult = $('Function: Conflict Detection').item.json;

const blockId = block.properties?.BLOCK_ID?.title?.[0]?.text?.content || block.id;
const content = block.properties?.CONTENT?.rich_text?.[0]?.text?.content || '';
const sourceAi = block.properties?.SOURCE_AI?.select?.name || 'unknown';
const timestamp = new Date().toISOString();

// DNA components
const dnaPrefix = 'CNSH';
const dnaType = 'BLOCK';
const dnaVersion = 'v2';

// Generate SHA256 hash of content + metadata
const hashInput = `${blockId}:${content.slice(0, 200)}:${sourceAi}:${timestamp}:${conflictResult.final_value_score}`;
const dnaHash = crypto.createHash('sha256').update(hashInput).digest('hex').slice(0, 16).toUpperCase();

// Full DNA string
const fullDNA = `${dnaPrefix}::${dnaType}::${dnaHash}::${dnaVersion}`;

// Parent DNA (if exists)
const parentDna = block.properties?.PARENT_BLOCK?.relation?.[0]?.id || null;

return [{
  json: {
    dna: fullDNA,
    dna_hash: dnaHash,
    dna_prefix: dnaPrefix,
    dna_type: dnaType,
    dna_version: dnaVersion,
    parent_dna: parentDna,
    origin: sourceAi,
    mutation_score: conflictResult.final_risk_score > 70 ? 80 : conflictResult.final_risk_score > 40 ? 40 : 10,
    integrity_status: conflictResult.conflict_flag ? '修复中' : '完整',
    generation_timestamp: timestamp,
    _audit: {
      input_length: content.length,
      hash_strength: 'SHA256/64bit',
      traceable: true
    }
  }
}];

// CNSH WUXING (FIVE ELEMENTS) SCORING ENGINE
// DNA: CNSH::FUNC::WUXING::v2.0
// 五行评分: 金=结构/木=生长/水=流动/火=能量/土=稳定

const gptOutput = $('Function: Conflict Detection').item.json.gpt_raw || {};
const claudeAudit = $('Function: Conflict Detection').item.json.claude_raw || {};
const content = $('Notion Trigger').item.json.properties?.CONTENT?.rich_text?.[0]?.text?.content || '';
const declaredElement = $('Notion Trigger').item.json.properties?.ELEMENT?.select?.name || '';

// Scoring formulas
const contentLength = content.length;

// 金 (Structure): Logic coherence, formatting, architecture
const jinScore = Math.min(100, Math.round(
  (claudeAudit.logic_score || 50) * 0.5 +
  (gptOutput.value_score || 50) * 0.3 +
  (contentLength > 100 ? 20 : 10)
));

// 木 (Growth): Expansion potential, derivative value
const muScore = Math.min(100, Math.round(
  (gptOutput.value_score || 50) * 0.6 +
  (100 - (claudeAudit.bias || 0) * 100) * 0.4
));

// 水 (Flow): Readability, connection strength
const shuiScore = Math.min(100, Math.round(
  (contentLength > 0 ? Math.min(100, contentLength / 10) : 50) +
  (claudeAudit.consensus_score || 50) * 0.5
));

// 火 (Energy): Innovation, risk, impact
const huoScore = Math.min(100, Math.round(
  ($('Function: Conflict Detection').item.json.final_risk_score || 50) * 0.4 +
  (gptOutput.risk_score || 50) * 0.3 +
  (claudeAudit.hallucination ? (1 - claudeAudit.hallucination) * 30 : 30)
));

// 土 (Stability): Reliability, grounding
const tuScore = Math.min(100, Math.round(
  (100 - ($('Function: Conflict Detection').item.json.hallucination_score || 0) * 100) * 0.4 +
  (claudeAudit.consensus_score || 50) * 0.3 +
  (100 - ($('Function: Conflict Detection').item.json.bias_score || 0) * 100) * 0.3
));

// Element classification if not declared
const elementScores = { '金': jinScore, '木': muScore, '水': shuiScore, '火': huoScore, '土': tuScore };
const dominantElement = declaredElement || Object.entries(elementScores)
  .sort((a, b) => b[1] - a[1])[0][0];

// Calculate composite scores
const avgScore = Math.round((jinScore + muScore + shuiScore + huoScore + tuScore) / 5);
const balanceScore = 100 - Math.round(
  Math.abs(jinScore - avgScore) +
  Math.abs(muScore - avgScore) +
  Math.abs(shuiScore - avgScore) +
  Math.abs(huoScore - avgScore) +
  Math.abs(tuScore - avgScore)
) / 5;

return [{
  json: {
    wuxing: {
      金: jinScore,
      木: muScore,
      水: shuiScore,
      火: huoScore,
      土: tuScore
    },
    dominant_element: dominantElement,
    balance_score: Math.max(0, balanceScore),
    composite_score: avgScore,
    formulas: {
      jin: 'logic_score*0.5 + value_score*0.3 + length_bonus',
      mu: 'value_score*0.6 + (1-bias)*100*0.4',
      shui: 'length_factor + consensus*0.5',
      huo: 'risk*0.4 + gpt_risk*0.3 + (1-hallucination)*30',
      tu: '(1-hallucination)*100*0.4 + consensus*0.3 + (1-bias)*100*0.3'
    },
    dna_trace: 'CNSH::WUXING::' + new Date().toISOString()
  }
}];

// CNSH TRICOLOR AUDIT MARKER
// DNA: CNSH::FUNC::TRICOLOR::v2.0
// 🔴🟡🟢 Three-color audit system for visual priority marking

const conflict = $('Function: Conflict Detection').item.json;
const wuxing = $('Function: Wuxing Scoring').item.json;

const valueScore = conflict.final_value_score || 0;
const riskScore = conflict.final_risk_score || 0;
const hallucination = conflict.hallucination_score || 0;
const logicScore = conflict.logic_score || 0;
const consensusScore = conflict.consensus_score || 0;

// Tricolor determination
let redFlags = [];
let yellowFlags = [];
let greenFlags = [];

// 🔴 RED conditions
if (riskScore >= 70) redFlags.push(`RISK:${riskScore}`);
if (conflict.conflict_flag) redFlags.push('CONFLICT');
if (hallucination > 0.6) redFlags.push(`HALLUCINATION:${hallucination.toFixed(2)}`);
if (logicScore < 40) redFlags.push(`LOGIC:${logicScore}`);

// 🟡 YELLOW conditions
if (riskScore >= 40 && riskScore < 70) yellowFlags.push(`RISK:${riskScore}`);
if (logicScore >= 40 && logicScore < 70) yellowFlags.push(`LOGIC:${logicScore}`);
if (consensusScore >= 40 && consensusScore < 70) yellowFlags.push(`CONSENSUS:${consensusScore}`);
if (wuxing.balance_score < 50) yellowFlags.push('UNBALANCED_WUXING');

// 🟢 GREEN conditions
if (valueScore >= 85) greenFlags.push(`VALUE:${valueScore}`);
if (consensusScore >= 80) greenFlags.push(`CONSENSUS:${consensusScore}`);
if (logicScore >= 80) greenFlags.push(`LOGIC:${logicScore}`);
if (riskScore < 40 && !conflict.conflict_flag) greenFlags.push('LOW_RISK');
if (wuxing.balance_score >= 70) greenFlags.push('BALANCED_WUXING');

// Final marker
let finalMarker;
let finalStatus;
if (redFlags.length > 0) {
  finalMarker = '🔴';
  finalStatus = 'BLOCKED';
} else if (yellowFlags.length > 0) {
  finalMarker = '🟡';
  finalStatus = 'REVIEW';
} else {
  finalMarker = '🟢';
  finalStatus = valueScore >= 85 ? 'ACTIVE' : 'DRAFT';
}

return [{
  json: {
    tricolor_marker: finalMarker,
    tricolor_status: finalStatus,
    red_flags: redFlags,
    yellow_flags: yellowFlags,
    green_flags: greenFlags,
    audit_summary: `${finalMarker} [${finalStatus}] R:${redFlags.length} Y:${yellowFlags.length} G:${greenFlags.length}`,
    recommendation: redFlags.length > 0 ? '需要人工审查' : yellowFlags.length > 0 ? '进入审查队列' : '可自动推进',
    dna_trace: 'CNSH::TRICOLOR::' + new Date().toISOString(),
    _meta: {
      version: '2.0',
      engine: 'TRICOLOR_AUDIT_v2',
      threshold_red: 70,
      threshold_yellow: 40,
      threshold_green: 85
    }
  }
}];
